const CHECK = ['Each statement is a common confusion in this section. Getting one wrong is useful, because the reason explains the idea.', 'Decide true or false before pressing, say why to yourself, and then read the explanation.'];

export const hasGuide = c => /Check$/.test(c) || !!GUIDES[c];
export function guideFor(component) {
  const [idea, how] = /Check$/.test(component) ? CHECK : GUIDES[component];
  return { idea, how };
}
